INSERT INTO blog_post_translations
  (post_id, locale, slug, title, excerpt, body_html, seo_title, seo_description)
VALUES (
  :post_id, 'uz', $x$genshin-impact-bannerlar$x$,
  $x$Genshin Impact bannerlari: qaysi biriga wish qilish kerak$x$,
  $x$Personaj uchun qaysi bannerga wish qilish, pity va 50/50 qanday ishlashi hamda behuda ketmasligi uchun qancha Primogem yigʻish kerakligi.$x$,
$x$<h2>Asosiysi</h2>
<ul>
<li>Aniq bir personaj kerak boʻlsa — faqat uning event bannerida wish qiling. Qurol va standart bannerlarning mukofotlari ham, hisoblagichlari ham boshqa.</li>
<li>5★ eng kechi bilan 90-wish’da kafolatlanadi, 4★ esa kamida har 10 wish’da bir marta tushadi.</li>
<li>50/50 sababli kerakli personajga eng yomon holatda 180 wish ketadi.</li>
<li>Bitta wish 160 Primogem turadi: bitta kafolatga 14 400 gacha, kerakli personajga 28 800 gacha. Genesis Crystal Primogem’ga 1:1 almashtiriladi.</li>
</ul>
<p>Genshin Impact’da wish’lar koʻringanidan koʻra oldindan aytib boʻladigan. Pity va 50/50 qanday hisoblanishini bilsangiz, byudjetni oldindan hisoblab, omadga emas, aniq maqsadga wish qilasiz.</p>
<h2>Banner turlari</h2>
<ul>
<li><strong>Personaj event banneri.</strong> Joriy versiyaning 5★ va 4★ personajlariga yuqori imkoniyat. Odatda bir vaqtda ikkitasi ochiq boʻladi va pity hisoblagichi ular uchun umumiy.</li>
<li><strong>Qurol event banneri.</strong> Ikkita 5★ qurolga yuqori imkoniyat. Hisoblagichi alohida, 5★ eng kechi bilan 80-wish’da kafolatlanadi. Kerakli qurol Epitomized Path orqali tanlanadi. Faqat aniq bir build uchun yigʻayotgan boʻlsangiz arziydi.</li>
<li><strong>Standart banner.</strong> Doimiy, 5★ personaj va qurollarning asosiy toʻplami bilan. Hisoblagichi event bannerlariga bogʻliq emas.</li>
</ul>
<p>Personaj ortidan quvayotgan boʻlsangiz — uning event bannerida wish qiling. Qurol va standart bannerlar bunga mos emas: mukofotlari boshqa, hisoblagichlari alohida.</p>
<h2>Pity va 50/50</h2>
<p>Pity — cheksiz behuda wish qilishingizga yoʻl qoʻymaydigan hisoblagich:</p>
<ul>
<li><strong>5★ — eng kechi bilan 90-wish’da.</strong> Asosiy imkoniyat har wish’da taxminan 0,6%, lekin taxminan 74-wish’dan keskin oshadi («soft pity»). Shuning uchun 5★ larning aksariyati 74- va 90-wish orasida tushadi.</li>
<li><strong>4★ — kamida har 10 wish’da bir marta.</strong> Bu hisoblagich alohida.</li>
</ul>
<p><strong>50/50.</strong> Personaj bannerida 5★ tushganda, bu taxminan teng ehtimol bilan yo banner personaji, yo standart toʻplamdan tasodifiy personaj boʻladi. Yutqazsangiz — keyingi 5★ albatta banner personaji boʻladi. 50/50 ni ketma-ket ikki marta yutqazib boʻlmaydi.</p>
<p>5.0 versiyadan beri oʻyinda Capturing Radiance mexanikasi bor: 50/50 ketma-ket bir necha marta yutqazilsa, keyingisini yutish imkoniyati oshadi.</p>
<p><strong>Hisoblagich koʻchadi.</strong> Personaj banneridagi pity banner almashganda saqlanadi: oldingi bannerda 5★ siz 50 wish qilgan boʻlsangiz, yangisini 50 dan boshlaysiz.</p>
<h2>Yangi personajlar yoki rerunlar: kimga yigʻish kerak</h2>
<p>Bannerlar taxminan har uch haftada almashadi: har bir versiyada ikki faza bor. Joriy faza jadvali oʻyinning oʻzida, wish boʻlimida koʻrinadi.</p>
<ul>
<li><strong>Yangi personaj debyuti</strong> — murakkab kontent oʻynaydiganlar uchun eng qimmatli banner: yangi personajlar koʻpincha metani belgilaydi.</li>
<li><strong>Rerun</strong> — personaj uzoq vaqt chiqmagan va jamoangizga haqiqatan kerak boʻlsa, arziydi: koʻplari bir necha versiyada bir marta qaytadi.</li>
<li><strong>Oʻtkazib yuboring</strong>, agar personaj sizda bor qahramonning rolini takrorlasa. Bitta bannerda tejalgan Primogem koʻpincha keyingisiga yetish-yetmasligini hal qiladi.</li>
</ul>
<p>Honkai: Star Rail ham oʻynaysizmi — u yerda mantiq bir xil; batafsil: <a href="/uz/blog/honkai-star-rail-toldirish">Honkai: Star Rail’ni qanday toʻldirish va nima sotib olish</a>.</p>
<h2>Qancha Primogem kerak</h2>
<p>Bitta wish — bitta fate, bitta fate — 160 Primogem.</p>
<ul>
<li><strong>10 wish:</strong> 1 600 Primogem — kamida bitta 4★.</li>
<li><strong>Bitta 5★ kafolati (90 wish):</strong> 14 400 Primogem gacha. Soft pity sababli odatda kamroq ketadi.</li>
<li><strong>Kerakli personaj aniq (180 wish gacha):</strong> 28 800 Primogem gacha — agar 50/50 yutqazilsa.</li>
</ul>
<p>Maqsaddan hisoblang va borini ayiring: joriy pity va topshiriq hamda eventlardan kelgan Primogem’lar. Faqat farqini sotib oling va 50/50 yutqazilsa, ozgina zaxira qoldiring.</p>
